 89→#[derive(Clone)]
 90→pub struct Repository {
 91→    pool: PgPool,
 92→}
 93→
 94→impl Repository {
 95→    pub fn new(pool: PgPool) -> Self {
 96→        Self { pool }
 97→    }
 98→
 99→    /// Crate-visible accessor for the connection pool (used by `v2_repo`).
100→    pub(crate) fn pool(&self) -> &PgPool {
101→        &self.pool
102→    }
