104→    /// Batch size for chunked inserts.
105→    const BATCH_SIZE: usize = 500;
106→
107→    pub async fn save_transactions(&self, txs: &[Transaction]) -> anyhow::Result<()> {
108→        for chunk in txs.chunks(Self::BATCH_SIZE) {
109→            let (query, args) = Self::build_transaction_insert(chunk)?;
110→            sqlx::query_with(&query, args).execute(&self.pool).await?;
111→        }
112→        Ok(())
113→    }
114→
115→    fn build_transaction_insert(
116→        chunk: &[Transaction],
117→    ) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
118→        let mut query = String::from(
119→            "INSERT INTO transactions (id, user_id, wallet_address, timestamp, tx_hash, chain, raw_metadata) VALUES ",
120→        );
121→        let mut args = sqlx::postgres::PgArguments::default();
122→        for (i, tx) in chunk.iter().enumerate() {
123→            let chain_str = chain_to_str(&tx.chain);
124→            let base = i * 7;
125→            if i > 0 {
126→                query.push_str(", ");
127→            }
128→            query.push_str(&format!(
129→                "(${}, ${}, ${}, ${}, ${}, ${}::chain_enum, ${})",
130→                base + 1,
131→                base + 2,
132→                base + 3,
133→                base + 4,
134→                base + 5,
135→                base + 6,
136→                base + 7
137→            ));
138→            use sqlx::Arguments;
139→            args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
140→            args.add(tx.user_id).map_err(|e| anyhow::anyhow!("{e}"))?;
141→            args.add(&tx.wallet_address)
142→                .map_err(|e| anyhow::anyhow!("{e}"))?;
143→            args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
144→            args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
145→            args.add(chain_str).map_err(|e| anyhow::anyhow!("{e}"))?;
146→            args.add(&tx.raw_metadata)
147→                .map_err(|e| anyhow::anyhow!("{e}"))?;
148→        }
149→        query.push_str(" ON CONFLICT (chain, tx_hash) DO NOTHING");
150→        Ok((query, args))
151→    }
