168→        for (i, entry) in chunk.iter().enumerate() {
169→            let entry_type_str = entry_type_to_str(&entry.entry_type);
170→            let base = i * 8;
171→            if i > 0 {
172→                query.push_str(", ");
173→            }
174→            query.push_str(&format!(
175→                "(${}, ${}, ${}, ${}, ${}, ${}, ${}::entry_type_enum, ${})",
176→                base + 1,
177→                base + 2,
178→                base + 3,
179→                base + 4,
180→                base + 5,
181→                base + 6,
182→                base + 7,
183→                base + 8
184→            ));
185→            use sqlx::Arguments;
186→            args.add(entry.id).map_err(|e| anyhow::anyhow!("{e}"))?;
187→            args.add(entry.transaction_id)
188→                .map_err(|e| anyhow::anyhow!("{e}"))?;
189→            args.add(entry.user_id)
190→                .map_err(|e| anyhow::anyhow!("{e}"))?;
191→            args.add(&entry.wallet_address)
192→                .map_err(|e| anyhow::anyhow!("{e}"))?;
193→            args.add(&entry.asset_symbol)
194→                .map_err(|e| anyhow::anyhow!("{e}"))?;
195→            args.add(&entry.amount)
196→                .map_err(|e| anyhow::anyhow!("{e}"))?;
197→            args.add(entry_type_str)
198→                .map_err(|e| anyhow::anyhow!("{e}"))?;
199→            args.add(&entry.fiat_value)
200→                .map_err(|e| anyhow::anyhow!("{e}"))?;
201→        }
202→        query.push_str(" ON CONFLICT (id) DO NOTHING");
203→        Ok((query, args))
204→    }
