224→    pub async fn get_transactions_by_wallet_filtered(
225→        &self,
226→        wallet: &str,
227→        limit: i64,
228→        offset: i64,
229→        from: Option<i64>,
230→        to: Option<i64>,
231→    ) -> anyhow::Result<Vec<Transaction>> {
232→        let mut sql = String::from(
233→            "SELECT id, user_id, wallet_address, timestamp, tx_hash, chain::text, raw_metadata \
234→             FROM transactions WHERE wallet_address = $1",
235→        );
236→        if from.is_some() {
237→            sql.push_str(" AND timestamp >= $4");
238→        }
239→        if to.is_some() {
240→            sql.push_str(if from.is_some() {
241→                " AND timestamp <= $5"
242→            } else {
243→                " AND timestamp <= $4"
244→            });
245→        }
246→        sql.push_str(" ORDER BY timestamp ASC LIMIT $2 OFFSET $3");
247→
248→        let mut query = sqlx::query(&sql).bind(wallet).bind(limit).bind(offset);
249→        if let Some(f) = from {
250→            query = query.bind(f);
251→        }
252→        if let Some(t) = to {
253→            query = query.bind(t);
254→        }
255→        let rows = query.fetch_all(&self.pool).await?;
256→
257→        let mut txs = Vec::new();
258→        for row in rows {
