292→
293→    pub async fn get_ledger_entries_by_wallet_filtered(
294→        &self,
295→        wallet: &str,
296→        limit: i64,
297→        offset: i64,
298→        from: Option<i64>,
299→        to: Option<i64>,
300→    ) -> anyhow::Result<Vec<LedgerEntry>> {
301→        let mut sql = String::from(
302→            "SELECT l.id, l.transaction_id, l.user_id, l.wallet_address, l.asset_symbol, \
303→             l.amount, l.entry_type::text, l.fiat_value \
304→             FROM ledger_entries l",
305→        );
306→        let needs_join = from.is_some() || to.is_some();
307→        if needs_join {
308→            sql.push_str(" JOIN transactions t ON l.transaction_id = t.id");
309→        }
310→        sql.push_str(" WHERE l.wallet_address = $1");
311→        let mut param_idx = 4_usize;
312→        if from.is_some() {
313→            sql.push_str(&format!(" AND t.timestamp >= ${param_idx}"));
314→            param_idx += 1;
315→        }
316→        if to.is_some() {
317→            sql.push_str(&format!(" AND t.timestamp <= ${param_idx}"));
318→        }
319→        sql.push_str(" ORDER BY l.created_at ASC LIMIT $2 OFFSET $3");
320→
321→        let mut query = sqlx::query(&sql).bind(wallet).bind(limit).bind(offset);
322→        if let Some(f) = from {
323→            query = query.bind(f);
324→        }
325→        if let Some(t) = to {
326→            query = query.bind(t);
327→        }
328→        let rows = query.fetch_all(&self.pool).await?;
329→
330→        let mut entries = Vec::new();
331→        for row in rows {
332→            let entry_type_str: String = row.try_get("entry_type")?;
333→            let entry_type = str_to_entry_type(&entry_type_str);
334→
335→            entries.push(LedgerEntry {
336→                id: row.try_get("id")?,
337→                transaction_id: row.try_get("transaction_id")?,
338→                user_id: row.try_get("user_id")?,
339→                wallet_address: row.try_get("wallet_address")?,
340→                asset_symbol: row.try_get("asset_symbol")?,
341→                amount: row.try_get("amount")?,
342→                entry_type,
343→                fiat_value: row.try_get("fiat_value")?,
344→            });
345→        }
346→        Ok(entries)
347→    }
348→
349→    pub async fn get_balances(
350→        &self,
351→        wallet: &str,
352→        at: Option<i64>,
353→    ) -> anyhow::Result<Vec<(String, bigdecimal::BigDecimal)>> {
354→        let rows = match at {
355→            Some(ts) => {
356→                sqlx::query(
357→                    r#"
358→                    SELECT le.asset_symbol, SUM(le.amount) as balance
359→                    FROM ledger_entries le
360→                    JOIN transactions t ON le.transaction_id = t.id
361→                    WHERE le.wallet_address = $1 AND t.timestamp <= $2
362→                    GROUP BY le.asset_symbol
363→                    HAVING SUM(le.amount) != 0
364→                    ORDER BY le.asset_symbol
365→                    "#,
366→                )
367→                .bind(wallet)
368→                .bind(ts)
369→                .fetch_all(&self.pool)
370→                .await?
371→            }
372→            None => {
373→                sqlx::query(
374→                    r#"
375→                    SELECT asset_symbol, SUM(amount) as balance
376→                    FROM ledger_entries
377→                    WHERE wallet_address = $1
378→                    GROUP BY asset_symbol
379→                    HAVING SUM(amount) != 0
380→                    ORDER BY asset_symbol
381→                    "#,
382→                )
383→                .bind(wallet)
384→                .fetch_all(&self.pool)
385→                .await?
386→            }
387→        };
388→
389→        let mut balances = Vec::new();
390→        for row in rows {
391→            balances.push((
392→                row.try_get::<String, _>("asset_symbol")?,
393→                row.try_get::<bigdecimal::BigDecimal, _>("balance")?,
394→            ));
395→        }
396→        Ok(balances)
397→    }
398→
399→    pub async fn get_checkpoint(
400→        &self,
401→        chain: &str,
402→        wallet: &str,
403→    ) -> anyhow::Result<Option<IndexerCheckpoint>> {
404→        let row = sqlx::query(
405→            r#"
406→            SELECT chain::text, wallet_address, last_signature, last_slot, last_block, last_timestamp
407→            FROM indexer_checkpoints
408→            WHERE chain = $1::chain_enum AND wallet_address = $2
409→            "#,
410→        )
411→        .bind(chain)
412→        .bind(wallet)
413→        .fetch_optional(&self.pool)
414→        .await?;
415→
416→        match row {
417→            Some(row) => {
418→                let chain_str: String = row.try_get("chain")?;
419→                let chain = str_to_chain(&chain_str)?;
420→                Ok(Some(IndexerCheckpoint {
421→                    chain,
422→                    wallet_address: row.try_get("wallet_address")?,
423→                    last_signature: row.try_get("last_signature")?,
424→                    last_slot: row.try_get("last_slot")?,
425→                    last_block: row.try_get("last_block")?,
426→                    last_timestamp: row.try_get("last_timestamp")?,
427→                }))
428→            }
