 703→    pub async fn create_dataset_version(&self, dv: &DatasetVersion) -> anyhow::Result<()> {
 704→        let (query, args) = build_dataset_version_insert(dv)?;
 705→        sqlx::query_with(&query, args).execute(self.pool()).await?;
 706→        Ok(())
 707→    }
 708→
 709→    pub async fn get_latest_dataset_version(
 710→        &self,
 711→        dataset_name: &str,
 712→    ) -> anyhow::Result<Option<DatasetVersion>> {
 713→        let row = sqlx::query(
 714→            "SELECT id, dataset_name, version, parser_hash, created_at, notes \
 715→             FROM dataset_versions WHERE dataset_name = $1 ORDER BY version DESC LIMIT 1",
 716→        )
 717→        .bind(dataset_name)
 718→        .fetch_optional(self.pool())
 719→        .await?;
 720→        row.as_ref().map(row_to_dataset_version).transpose()
 721→    }
 722→}
