  1→use clap::{Parser, Subcommand};
  2→use spectraplex_adapters::{
  3→    evm::EvmAdapter,
  4→    evm_parser,
  5→    hyperliquid::HyperliquidAdapter,
  6→    hyperliquid_parser,
  7→    repo::{build_checkpoint, Repository},
  8→    solana::SolanaAdapter,
  9→    solana_grpc::SolanaGrpcAdapter,
 10→    solana_parser,
 11→};
 12→use spectraplex_core::models::{ChainIngestor, Transaction};
 13→use sqlx::postgres::PgPoolOptions;
 14→use std::fs::File;
 15→use std::io::{BufRead, BufReader, Write};
 16→use std::path::PathBuf;
 17→use tracing::{error, info, warn};
 18→use uuid::Uuid;
 19→
 20→#[derive(Parser)]
 21→#[command(about = "Spectraplex CLI", long_about = None)]
 22→struct Cli {
 23→    #[arg(global = true, long, env = "DATABASE_URL")]
 24→    db_url: Option<String>,
 25→
 26→    #[command(subcommand)]
 27→    command: Commands,
 28→}
 29→
 30→#[derive(Subcommand)]
 31→enum Commands {
 32→    /// Initialize the database schema
 33→    InitDb,
 34→
 35→    /// Ingest raw data from blockchain to Bronze layer (JSONL)
 36→    Ingest {
 37→        #[arg(short, long)]
 38→        chain: String,
 39→
 40→        /// Wallet address(es) to ingest. Pass multiple times for batch ingestion.
 41→        #[arg(short, long, required = true, num_args = 1..)]
 42→        wallet: Vec<String>,
 43→
 44→        #[arg(short, long, default_value = "bronze_transactions.jsonl")]
 45→        output: PathBuf,
 46→
 47→        #[arg(long)]
 48→        rpc: Option<String>,
 49→
 50→        #[arg(long)]
 51→        grpc_url: Option<String>,
 52→
 53→        #[arg(long)]
 54→        x_token: Option<String>,
 55→
 56→        #[arg(long, default_value_t = 10)]
 57→        limit: usize,
 58→
 59→        /// User ID to associate with ingested transactions. Auto-generates if not provided.
 60→        #[arg(long)]
 61→        user_id: Option<Uuid>,
 62→    },
 63→    /// Normalize Bronze data to Silver layer (Ledger Entries)
 64→    Normalize {
 65→        #[arg(short, long, default_value = "bronze_transactions.jsonl")]
 66→        input: PathBuf,
 67→
 68→        #[arg(short, long, default_value = "silver_ledger.jsonl")]
 69→        output: PathBuf,
 70→    },
 71→}
 72→
 73→#[tokio::main]
 74→async fn main() -> anyhow::Result<()> {
 75→    dotenvy::dotenv().ok();
 76→
 77→    tracing_subscriber::fmt()
 78→        .with_env_filter(
 79→            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
 80→        )
 81→        .init();
 82→
 83→    let cli = Cli::parse();
 84→
 85→    // Setup DB Pool if URL provided
 86→    let pool = if let Some(url) = &cli.db_url {
 87→        Some(PgPoolOptions::new().max_connections(5).connect(url).await?)
 88→    } else {
 89→        None
 90→    };
 91→
 92→    match cli.command {
 93→        Commands::InitDb => {
 94→            if let Some(p) = pool {
 95→                info!("Running migrations...");
 96→                sqlx::migrate!("../migrations").run(&p).await?;
 97→                info!("Database initialized successfully.");
 98→            } else {
 99→                error!("--db-url is required for InitDb");
100→            }
101→        }
102→        Commands::Ingest {
103→            chain,
104→            wallet: wallets,
105→            output,
106→            rpc,
107→            grpc_url,
108→            x_token,
109→            limit,
110→            user_id,
111→        } => {
112→            let user_id = user_id.unwrap_or_else(|| {
113→                let id = Uuid::new_v4();
114→                info!(user_id = %id, "No --user-id provided, auto-generated");
115→                id
116→            });
117→
118→            for wallet in &wallets {
119→                info!(wallet = %wallet, chain = %chain, "Starting ingestion");
120→
121→                let checkpoint = if let Some(ref p) = pool {
122→                    let repo = Repository::new(p.clone());
123→                    match repo.get_checkpoint(&chain, wallet).await? {
124→                        Some(cp) => {
125→                            info!(
126→                                chain = %chain,
127→                                wallet = %wallet,
128→                                last_signature = ?cp.last_signature,
129→                                last_slot = ?cp.last_slot,
130→                                last_block = ?cp.last_block,
131→                                last_timestamp = ?cp.last_timestamp,
132→                                "Resuming from checkpoint"
133→                            );
134→                            Some(cp)
135→                        }
136→                        None => {
137→                            info!(chain = %chain, wallet = %wallet, "No existing checkpoint, full ingestion");
138→                            None
139→                        }
140→                    }
141→                } else {
142→                    None
143→                };
144→
145→                let events = match chain.as_str() {
146→                    "solana" => {
147→                        if let Some(ref endpoint) = grpc_url {
148→                            let adapter = SolanaGrpcAdapter::new(endpoint, x_token.clone());
149→                            if let Some(ref cp) = checkpoint {
150→                                if let Some(slot) = cp.last_slot {
151→                                    adapter.checkpoint().update(slot as u64);
152→                                }
153→                            }
154→                            adapter
155→                                .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
156→                                .await?
157→                        } else if let Some(ref rpc_url) = rpc {
158→                            let adapter = SolanaAdapter::new(rpc_url);
159→                            adapter
160→                                .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
161→                                .await?
162→                        } else {
163→                            anyhow::bail!("Either --grpc-url or --rpc must be provided for Solana");
164→                        }
165→                    }
166→                    "hyperliquid" => {
167→                        let adapter = HyperliquidAdapter::new();
168→                        adapter
169→                            .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
170→                            .await?
171→                    }
172→                    "ethereum" => {
173→                        let rpc_url = rpc
174→                            .as_ref()
175→                            .ok_or_else(|| anyhow::anyhow!("--rpc is required for Ethereum"))?;
176→                        let adapter = EvmAdapter::new(rpc_url)?;
177→                        adapter
178→                            .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
179→                            .await?
180→                    }
181→                    _ => {
182→                        warn!(chain = %chain, "Unsupported chain");
183→                        return Ok(());
184→                    }
185→                };
186→
187→                if let Some(ref p) = pool {
188→                    let repo = Repository::new(p.clone());
189→                    if let Some(cp) = build_checkpoint(&chain, wallet, &events) {
190→                        repo.save_transactions_and_checkpoint(&events, &cp).await?;
191→                        info!(count = events.len(), wallet = %wallet, "Saved transactions to database");
192→                        info!(
193→                            chain = %chain,
194→                            wallet = %wallet,
195→                            last_signature = ?cp.last_signature,
196→                            last_slot = ?cp.last_slot,
197→                            last_block = ?cp.last_block,
198→                            last_timestamp = ?cp.last_timestamp,
199→                            "Checkpoint saved atomically"
200→                        );
201→                    } else {
202→                        repo.save_transactions(&events).await?;
203→                        info!(
204→                            count = events.len(),
205→                            wallet = %wallet,
206→                            "Saved transactions to database (no checkpoint)"
207→                        );
208→                    }
209→                } else {
210→                    let mut file = File::create(&output)?;
211→                    for event in events {
212→                        serde_json::to_writer(&file, &event)?;
213→                        writeln!(file)?;
214→                    }
215→                    info!(path = ?output, wallet = %wallet, "Data written to file");
216→                }
217→            }
218→        }
219→        Commands::Normalize { input, output } => {
220→            let input_str = input.to_string_lossy();
221→            let transactions = if input_str.starts_with("db:") {
222→                let wallet = input_str.strip_prefix("db:").unwrap();
223→                let p = pool
224→                    .clone()
225→                    .ok_or_else(|| anyhow::anyhow!("--db-url is required for db: input"))?;
226→                info!(wallet = %wallet, "Fetching transactions from DB");
227→                let repo = Repository::new(p);
228→                repo.get_transactions_by_wallet(wallet).await?
229→            } else {
230→                info!(path = ?input, "Reading raw data from file");
231→                let file = File::open(&input)?;
232→                let reader = BufReader::new(file);
233→                reader
234→                    .lines()
235→                    .map(|line| {
236→                        let line = line?;
237→                        Ok(serde_json::from_str(&line)?)
238→                    })
239→                    .collect::<anyhow::Result<Vec<Transaction>>>()?
240→            };
241→
242→            let mut all_entries = Vec::new();
243→
244→            for tx in transactions {
245→                let result = match tx.chain {
246→                    spectraplex_core::models::Chain::Solana => {
247→                        solana_parser::parse_solana_transaction(&tx)
248→                    }
249→                    spectraplex_core::models::Chain::Hyperliquid => {
250→                        hyperliquid_parser::parse_hyperliquid_transaction(&tx)
251→                    }
252→                    spectraplex_core::models::Chain::Ethereum => {
253→                        evm_parser::parse_evm_transaction(&tx)
254→                    }
255→                };
256→                match result {
257→                    Ok(entries) => all_entries.extend(entries),
258→                    Err(e) => {
259→                        warn!(tx_hash = %tx.tx_hash, error = %e, "Skipping unparseable transaction");
260→                    }
261→                }
262→            }
263→
264→            if let Some(p) = pool {
265→                info!(
266→                    count = all_entries.len(),
267→                    "Saving ledger entries to database"
268→                );
269→                let repo = Repository::new(p);
270→                repo.save_ledger_entries(&all_entries).await?;
271→                info!("Normalization complete");
272→            } else {
273→                let mut out_file = File::create(&output)?;
274→                for entry in all_entries {
275→                    serde_json::to_writer(&out_file, &entry)?;
276→                    writeln!(out_file)?;
277→                }
278→                info!(path = ?output, "Normalization complete, output written to file");
279→            }
280→        }
281→    }
282→
283→    Ok(())
284→}
