        assert_eq!(chain_to_default_source(&Chain::Hyperliquid), "rest");
    }

    // -- V1 → V2 Transaction conversion --

    fn make_solana_tx() -> Transaction {
        Transaction {
            id: Uuid::new_v4(),
            user_id: Uuid::new_v4(),
            wallet_address: "REDACTED".to_string(),
            timestamp: 1700000000,
            tx_hash: "5VERv8NMhzg".to_string(),
            chain: Chain::Solana,
