    }

    fn make_eth_tx() -> Transaction {
        Transaction {
            id: Uuid::new_v4(),
            user_id: Uuid::new_v4(),
            wallet_address: "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48".to_string(),
            timestamp: 1700000000,
            tx_hash: "0xdeadbeef".to_string(),
