struct AppError {
    status: StatusCode,
    message: String,
}

impl AppError {
    fn internal(e: impl std::fmt::Display) -> Self {
        error!(error = %e, "Internal server error");
        Self {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            message: "Internal server error".to_string(),
        }
    }

    fn not_found(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::NOT_FOUND,
            message: msg.into(),
        }
    }

    fn bad_request(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::BAD_REQUEST,
            message: msg.into(),
        }
    }

    fn service_unavailable(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::SERVICE_UNAVAILABLE,
            message: msg.into(),
        }
    }

    fn forbidden(msg: impl Into<String>) -> Self {
        Self {
            status: StatusCode::FORBIDDEN,
            message: msg.into(),
        }
    }
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        error!(status = %self.status, error = %self.message);
        let body = serde_json::json!({ "error": self.message });
        (self.status, Json(body)).into_response()
    }
}

const MAX_CONCURRENT_JOBS: usize = 10;
const MAX_CONCURRENT_STREAMS: usize = 5;

struct AppState {
    repo: Repository,
    config: AppConfig,
    allowed_wallets: Option<HashSet<String>>,
    jobs: RwLock<HashMap<Uuid, JobEntry>>,
    job_semaphore: Arc<Semaphore>,
    streams: RwLock<HashMap<Uuid, StreamEntry>>,
    stream_semaphore: Arc<Semaphore>,
}

struct StreamEntry {
    id: Uuid,
    cancel: CancellationToken,
