    async fn test_semaphore_limits_concurrent_jobs() {
        let pool = PgPoolOptions::new()
            .connect_lazy("postgres://fake:fake@localhost/fake")
            .unwrap();
        let config = AppConfig {
            api_key: Some("secret".to_string()),
