            transactions_ingested: 5000,
            last_slot: 300000,
        };
        let json = serde_json::to_value(&info).unwrap();
        assert_eq!(json["uptime_secs"], 120);
        assert_eq!(json["transactions_ingested"], 5000);
        assert_eq!(json["last_slot"], 300000);
    }
}

